<div class="page-header"><h2><?= lang('inventory') ?></h2></div>
<div class="card"><table class="table data-table" data-source="<?= site_url('inventory/data') ?>" data-fields="warehouse_name,code,name,quantity,alert_quantity"><thead><tr><th><?= lang('warehouse') ?></th><th><?= lang('code') ?></th><th><?= lang('product') ?></th><th><?= lang('quantity') ?></th><th><?= lang('alert_quantity') ?></th></tr></thead><tbody>
<?php foreach ($items as $item): ?><tr class="<?= $item['quantity'] <= $item['alert_quantity'] ? 'table-warning' : '' ?>"><td><?= e($item['warehouse_name']) ?></td><td><?= e($item['code']) ?></td><td><?= e($item['name']) ?></td><td><?= e($item['quantity']) ?></td><td><?= e($item['alert_quantity']) ?></td></tr><?php endforeach; ?>
</tbody></table></div>
<?php if ($current_user['role'] === ROLE_ADMIN): ?><div class="card mt-3"><div class="card-body"><h3 class="card-title"><?= lang('inventory_adjustment') ?></h3><?= form_open('inventory/adjust') ?><div class="row"><div class="col-md-3 mb-2"><label class="form-label"><?= lang('warehouse') ?></label><select class="form-select" name="warehouse_id" required><?php foreach ($warehouses as $warehouse): ?><option value="<?= $warehouse['id'] ?>"><?= e($lang === 'ar' ? $warehouse['name_ar'] : $warehouse['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-3 mb-2"><label class="form-label"><?= lang('product') ?></label><select class="form-select" name="product_id" required><?php foreach ($products as $product): ?><option value="<?= $product['id'] ?>"><?= e($product['code'] . ' — ' . ($lang === 'ar' ? $product['name_ar'] : $product['name'])) ?></option><?php endforeach; ?></select></div><div class="col-md-2 mb-2"><label class="form-label"><?= lang('adjustment_type') ?></label><select class="form-select" name="mode"><option value="set"><?= lang('set_final_quantity') ?></option><option value="add"><?= lang('add_stock') ?></option><option value="remove"><?= lang('remove_stock') ?></option></select></div><div class="col-md-2 mb-2"><label class="form-label"><?= lang('quantity') ?></label><input class="form-control" name="quantity" type="number" min="0" required></div><div class="col-md-2 mb-2"><label class="form-label"><?= lang('adjustment_reason') ?></label><input class="form-control" name="reason" maxlength="255" placeholder="<?= e(lang('required_for_add_remove')) ?>"></div><div class="col-12"><p class="text-muted mb-2"><?= lang('inventory_adjustment_help') ?></p><button class="btn btn-primary" type="submit"><?= lang('save') ?></button></div></div><?= form_close() ?></div></div><?php endif; ?>
